//! The traces of the Rust structures outside the heap that hold values: what
//! each reports to a root provider's [`SlotVisitor`], generated by
//! `#[derive(Trace)]` from its fields (#686, `PRD/GC_PRD.md` §14).
//!
//! A trace written by hand misses what nobody tells it about: every edge a
//! collection has missed so far was in one (two in #38, one in #47, and
//! `CompiledMacro.foreign_expansions` until #623). A derived trace follows
//! the types instead, so a field cannot go untraced silently.

use std::cell::{Cell, OnceCell, RefCell};
use std::collections::{HashMap, HashSet, VecDeque};
use std::rc::{Rc, Weak};

use smallvec::{Array, SmallVec};

use super::gc::SlotVisitor;
use crate::TaggedValue;
use crate::cont_value::ContEnv;
use crate::continuation::CpsContinuation;
use crate::cps_expr::CpsExpr;
use crate::environment::Environment;
use crate::scope::{ScopeId, ScopeSet};

/// A structure outside the heap that holds values, which it reports to a
/// [`SlotVisitor`] when a collection asks.
///
/// Derived, never written by hand: `#[derive(Trace)]` traces every field
/// through its type's `Trace`. A field whose type has none does not compile,
/// and a field is left out only by `#[trace(skip, reason = "…")]`, whose
/// reason says what it holds instead of a value. Two attributes shape the
/// walk itself, for the structures as deep as the computation or the code
/// they stand for (#617):
/// - an enum variant's `#[trace(tail)]` field, a `Box<Self>`, continues the
///   trace in a loop, so that a continuation's chain, as deep as the
///   program's recursion, does not grow the native stack;
/// - a type's `#[trace(grows_stack_if = method)]` makes sure of the stack
///   before each level whose `method` says it nests, as every walk of code
///   does: a macro's patterns and templates.
///
/// The leaves are the slot visitor's:
/// - [`TaggedValue`], pinned: a copy, whose referent nothing moves before
///   the structure holding it becomes heap data;
/// - `Cell<TaggedValue>`, a slot: the value where it lives; and
///   `Cell<Option<TaggedValue>>`, pinned;
/// - `Rc<Environment>`, `Rc<CpsContinuation>`, [`ContEnv`] and `Rc<CpsExpr>`,
///   handed over whole, for the visitor to walk once however many paths
///   reach them; and `Weak<Environment>`, while something else holds it;
/// - and the containers that hold them: `Option`, `Box`, references,
///   slices, arrays, `Vec`, `VecDeque`, `SmallVec`, `RefCell`, `OnceCell`,
///   `Rc<[T]>`, the keys and values of a `HashMap` and the members of a
///   `HashSet`, and pairs and triples; and an `Rc` of a structure marked
///   [`TraceThroughRc`], traced wherever the `Rc` is reached.
///
/// Names (`str`, `String`, `Rc<str>`), scope sets and scope ids trace as
/// nothing: they cannot hold a value, and they sit beside values where a
/// field cannot be skipped on its own, in a binding's slot or a map's key.
/// Nothing else that holds no value implements it, integers included, which
/// can hold a value's bits: a field like that is skipped, with its reason.
///
/// ```
/// use patina_core::{TaggedValue, Trace};
///
/// #[derive(Trace)]
/// struct Frame {
///     procedure: TaggedValue,
///     arguments: Vec<TaggedValue>,
///     #[trace(skip, reason = "a frame depth")]
///     depth: usize,
/// }
/// ```
///
/// A field whose type has no `Trace` does not compile:
///
/// ```compile_fail
/// use patina_core::{TaggedValue, Trace};
///
/// #[derive(Trace)]
/// struct Frame {
///     procedure: TaggedValue,
///     arguments: Vec<TaggedValue>,
///     depth: usize,
/// }
/// ```
///
/// Nor does a field skipped without its reason:
///
/// ```compile_fail
/// use patina_core::{TaggedValue, Trace};
///
/// #[derive(Trace)]
/// struct Frame {
///     procedure: TaggedValue,
///     arguments: Vec<TaggedValue>,
///     #[trace(skip)]
///     depth: usize,
/// }
/// ```
pub trait Trace {
    /// Report every value `self` holds to `visitor`.
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V);

    /// Report a run of these, as a slice, a `Vec` or an array holds them: one
    /// at a time, unless the type knows better. A run of slots goes to the
    /// visitor in one call ([`SlotVisitor::slots`]), as a register file is
    /// reported, so that a root provider's dynamic dispatch is paid once for
    /// the run rather than once a slot.
    fn trace_slice<V: SlotVisitor + ?Sized>(slice: &[Self], visitor: &mut V)
    where
        Self: Sized,
    {
        for item in slice {
            item.trace(visitor);
        }
    }
}

impl Trace for TaggedValue {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        visitor.pinned(*self);
    }
}

impl Trace for Cell<TaggedValue> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        visitor.slot(self);
    }

    fn trace_slice<V: SlotVisitor + ?Sized>(slice: &[Self], visitor: &mut V) {
        visitor.slots(slice);
    }
}

impl Trace for Rc<Environment> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        visitor.env(self);
    }
}

impl Trace for Rc<CpsContinuation> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        visitor.continuation(self);
    }
}

impl Trace for ContEnv {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        visitor.cont_env(self);
    }
}

impl Trace for Rc<CpsExpr> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        visitor.expr_literals(self);
    }
}

impl<T: Trace> Trace for Option<T> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        if let Some(value) = self {
            value.trace(visitor);
        }
    }
}

impl<T: Trace + ?Sized> Trace for Box<T> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        (**self).trace(visitor);
    }
}

impl<T: Trace> Trace for [T] {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        T::trace_slice(self, visitor);
    }
}

impl<T: Trace, const N: usize> Trace for [T; N] {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        self.as_slice().trace(visitor);
    }
}

impl<T: Trace> Trace for Vec<T> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        self.as_slice().trace(visitor);
    }
}

impl<T: Trace> Trace for VecDeque<T> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        let (front, back) = self.as_slices();
        T::trace_slice(front, visitor);
        T::trace_slice(back, visitor);
    }
}

/// What a reference refers to, as a root provider that borrows the state it
/// reports holds it.
impl<T: Trace + ?Sized> Trace for &T {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        (**self).trace(visitor);
    }
}

/// A slice shared through `Rc`, as a wind record's handler stack is, traced
/// wherever it is reached, as the walk written by hand traced it.
impl<T: Trace> Trace for Rc<[T]> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        (**self).trace(visitor);
    }
}

/// A structure an `Rc` holds whose trace runs wherever an `Rc` to it is
/// reached, rather than going to the visitor to walk once: one traced from
/// one place, as the VM traces each code object from its code store and its
/// step tracer from its state. A structure many paths share goes to the
/// visitor instead, which walks it once however it is reached: an
/// environment, a continuation, code (`Rc<Environment>`, `Rc<CpsContinuation>`,
/// `Rc<CpsExpr>`).
///
/// A marker, implemented by the structure's own crate, since no crate but
/// this one may implement `Trace` for an `Rc`. A `RefCell` of one is one.
pub trait TraceThroughRc: Trace {}

impl<T: TraceThroughRc + ?Sized> TraceThroughRc for RefCell<T> {}

impl<T: TraceThroughRc + ?Sized> Trace for Rc<T> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        (**self).trace(visitor);
    }
}

/// A value that may be absent, in a cell: pinned, since only a
/// `Cell<TaggedValue>` is a slot.
impl Trace for Cell<Option<TaggedValue>> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        if let Some(value) = self.get() {
            visitor.pinned(value);
        }
    }
}

/// An environment held weakly, as the handle table holds the ones hosts lend
/// it (#620): traced for as long as something else holds it.
impl Trace for Weak<Environment> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        if let Some(env) = self.upgrade() {
            visitor.env(&env);
        }
    }
}

/// A table the heap keeps in Rust, read for the trace.
impl<T: Trace> Trace for super::table::HeapTable<T> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        self.with(|state| state.trace(visitor));
    }
}

/// Borrowed for the trace, as every hand-written trace borrowed its tables:
/// a collection while one is borrowed mutably is a bug, and panics.
impl<T: Trace + ?Sized> Trace for RefCell<T> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        self.borrow().trace(visitor);
    }
}

impl<T: Trace> Trace for OnceCell<T> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        if let Some(value) = self.get() {
            value.trace(visitor);
        }
    }
}

impl<A: Array> Trace for SmallVec<A>
where
    A::Item: Trace,
{
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        self.as_slice().trace(visitor);
    }
}

impl<K: Trace, T: Trace, S> Trace for HashMap<K, T, S> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        for (key, value) in self {
            key.trace(visitor);
            value.trace(visitor);
        }
    }
}

impl<T: Trace, S> Trace for HashSet<T, S> {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        for member in self {
            member.trace(visitor);
        }
    }
}

/// What cannot hold a value and sits beside values, in a binding's slot or a
/// map's key: a name, a scope set, a scope id.
macro_rules! trace_as_nothing {
    ($($held:ty),* $(,)?) => {
        $(
            impl Trace for $held {
                #[inline]
                fn trace<V: SlotVisitor + ?Sized>(&self, _: &mut V) {}
            }
        )*
    };
}

trace_as_nothing!(str, String, Rc<str>, ScopeSet, ScopeId);

impl<A: Trace, B: Trace> Trace for (A, B) {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        let (a, b) = self;
        a.trace(visitor);
        b.trace(visitor);
    }
}

impl<A: Trace, B: Trace, C: Trace> Trace for (A, B, C) {
    fn trace<V: SlotVisitor + ?Sized>(&self, visitor: &mut V) {
        let (a, b, c) = self;
        a.trace(visitor);
        b.trace(visitor);
        c.trace(visitor);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::compiled_macro::Pattern;
    use crate::cont_value::{ContValue, ExceptionHandler};

    /// Counts the values it is given, and is given nothing else.
    #[derive(Default)]
    struct Count(usize);

    impl SlotVisitor for Count {
        fn slot(&mut self, _: &Cell<TaggedValue>) {
            self.0 += 1;
        }
        fn pinned(&mut self, _: TaggedValue) {
            self.0 += 1;
        }
        fn env(&mut self, _: &Rc<Environment>) {
            unreachable!("the chain holds no environment")
        }
        fn continuation(&mut self, _: &Rc<CpsContinuation>) {
            unreachable!("the chain holds no continuation")
        }
        fn cont_env(&mut self, _: &ContEnv) {
            unreachable!("the chain holds no continuation environment")
        }
        fn expr_literals(&mut self, _: &CpsExpr) {
            unreachable!("the chain holds no code")
        }
    }

    /// A chain of continuation values is walked in a loop, through each
    /// variant's `tail`: one as deep as a program's recursion traces on a
    /// stack that a call per link would overflow (#617). The links are
    /// `RaiseHandlerReturn`s, whose tail is not their last traced field, so a
    /// call per link could not be turned into a loop by the optimizer: this
    /// test overflows if the `tail` is taken off.
    #[test]
    fn a_continuation_chain_is_traced_in_a_loop() {
        const LINKS: usize = 100_000;
        let traced = std::thread::Builder::new()
            .stack_size(128 * 1024)
            .spawn(|| {
                let mut chain = ContValue::Halt;
                for i in 0..LINKS {
                    chain = ContValue::RaiseHandlerReturn {
                        continuable: true,
                        original_exception: Some(TaggedValue::fixnum(i as i64)),
                        original_cont: Box::new(chain),
                        popped_handler: Some(ExceptionHandler {
                            handler: TaggedValue::fixnum(i as i64),
                        }),
                    };
                }
                let mut count = Count::default();
                chain.trace(&mut count);
                // Taken apart link by link: the default drop recurses.
                while let ContValue::RaiseHandlerReturn { original_cont, .. } = chain {
                    chain = *original_cont;
                }
                count.0
            })
            .expect("the thread starts")
            .join()
            .expect("the trace does not overflow the thread's stack");
        // Each link's exception and handler.
        assert_eq!(traced, 2 * LINKS);
    }

    /// A macro's pattern traces as deep as it nests, growing the stack where
    /// it does (`#[trace(grows_stack_if = is_nested)]`, #617): one nested
    /// 100,000 deep traces on a 128 KiB stack. This test overflows if the
    /// attribute is taken off.
    #[test]
    fn a_deep_pattern_is_traced_on_a_small_stack() {
        const DEPTH: usize = 100_000;
        let traced = std::thread::Builder::new()
            .stack_size(128 * 1024)
            .spawn(|| {
                let mut pattern = Pattern::Literal(TaggedValue::fixnum(1));
                for _ in 0..DEPTH {
                    pattern = Pattern::List(vec![pattern]);
                }
                let mut count = Count::default();
                pattern.trace(&mut count);
                count.0
            })
            .expect("the thread starts")
            .join()
            .expect("the trace does not overflow the thread's stack");
        assert_eq!(traced, 1);
    }
}
